  static String forStage(KrLanguage language, String heroId, int stage) =>
      stories[heroId]?[stage]?[language] ?? stories[heroId]?[stage]?[KrLanguage.english] ?? '';

  static String title(KrLanguage language) => switch (language) {
    KrLanguage.english => 'CARD STORY',
    KrLanguage.italian => 'STORIA DELLA CARTA',
    KrLanguage.spanish => 'HISTORIA DE LA CARTA',
    KrLanguage.japanese => 'カードの物語',
    KrLanguage.korean => '카드 이야기',
    KrLanguage.chinese => '卡牌故事',
    KrLanguage.german => 'KARTENGESCHICHTE',
  };
